package dev.starfold;

import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.level.block.EntityBlock;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import org.junit.jupiter.api.Test;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;

class NativeScopeTest {
    @org.junit.jupiter.api.BeforeAll static void boot(){NativePlanetEcologyTest.boot();}
    @Test void sixDirectionsHaveModelsAndAnUntickedEntity()throws Exception{var block=BuiltInRegistries.BLOCK.get(ResourceLocation.parse("starfold:scope"));var variants=NativeFlightPermitTest.json("assets/starfold/blockstates/scope.json").getAsJsonObject("variants");assertEquals(6,variants.size());for(var d:Direction.values()){var state=block.defaultBlockState().setValue(BlockStateProperties.FACING,d);var entity=((EntityBlock)block).newBlockEntity(BlockPos.ZERO,state);assertInstanceOf(NativeThruster.Scope.class,entity);assertEquals("starfold:scope",BuiltInRegistries.BLOCK_ENTITY_TYPE.getKey(entity.getType()).toString());assertNull(((EntityBlock)block).getTicker(null,state,entity.getType()));assertNotNull(variants.get("facing="+d.getSerializedName()));assertEquals(new net.minecraft.world.phys.AABB(0,0,0,1,1,1),state.getCollisionShape(net.minecraft.world.level.EmptyBlockGetter.INSTANCE,BlockPos.ZERO).bounds());}}
    @Test void upgradeTiersHaveEntitiesRecipesToolsAndDistinctArt()throws Exception{String lower="scope";for(int tier=2;tier<=3;tier++){String name=tier==2?"scope_nav":"scope_precise";var id=ResourceLocation.parse("starfold:"+name);var block=BuiltInRegistries.BLOCK.get(id);assertInstanceOf(NativeThruster.ScopeBlock.class,block);assertEquals(tier,((NativeThruster.ScopeBlock)block).tier);assertEquals(id,BuiltInRegistries.ITEM.getKey(block.asItem()));for(var d:Direction.values()){var state=block.defaultBlockState().setValue(BlockStateProperties.FACING,d);var entity=((EntityBlock)block).newBlockEntity(BlockPos.ZERO,state);assertEquals(tier,((NativeThruster.Scope)entity).tier());assertTrue(entity.getType().isValid(state));}assertEquals(6,NativeFlightPermitTest.json("assets/starfold/blockstates/"+name+".json").getAsJsonObject("variants").size());var recipe=NativeFlightPermitTest.json("data/starfold/recipe/"+name+".json");assertEquals("starfold:"+lower,recipe.getAsJsonObject("key").getAsJsonObject("S").get("item").getAsString());assertTrue(NativeFlightPermitTest.json("data/starfold/loot_table/blocks/"+name+".json").toString().contains(id.toString()));for(String tag:new String[]{"mineable/pickaxe","needs_iron_tool"})assertTrue(NativeFlightPermitTest.json("data/minecraft/tags/block/"+tag+".json").toString().contains(id.toString()));for(String part:new String[]{"housing","lens"}){var art=javax.imageio.ImageIO.read(Path.of("src/main/resources/assets/starfold/textures/block/"+name+"_"+part+".png").toFile());assertEquals(16,art.getWidth());assertNotEquals(art.getRGB(0,0),art.getRGB(7,7));}lower=name;}}
    @Test void housingAndLensAreGeneratedSixteenPixelArt()throws Exception{for(var name:new String[]{"scope_housing","scope_lens"}){var image=javax.imageio.ImageIO.read(Path.of("src/main/resources/assets/starfold/textures/block/"+name+".png").toFile());assertEquals(16,image.getWidth());assertEquals(16,image.getHeight());assertNotEquals(image.getRGB(0,0),image.getRGB(7,7));}assertEquals(2,NativeFlightPermitTest.json("assets/starfold/models/block/scope.json").getAsJsonArray("elements").size());}
    @Test void scopeUsesRenderPoseRealCameraAndSessionHullIdentity()throws Exception{var s=Files.readString(Path.of("src/main/java/dev/starfold/NativeHelmClient.java"));assertEquals(.6,NativeHelmClient.SCOPE_OUT);for(var token:new String[]{"getUniqueId()","getBlockEntities().values()","body.renderPose(partial)","camera.rotation().set(rotation)","camera.getLookVector()","camera.getUpVector()","if(!scopeView()&&mc.options.getCameraType()==CameraType.THIRD_PERSON_BACK)zoom=","cycle.add(FIRST)","90/Math.max"})assertTrue(s.contains(token),token);}
    @Test void surfaceMarkerProjectsAPointButKeepsObserverAndGuidanceIndependent()throws Exception{var s=Files.readString(Path.of("src/main/java/dev/starfold/NativeWaypointClient.java"));assertTrue(s.contains("var eye=context.camera().getPosition()"));assertTrue(s.contains("hull.x+direction.x()-eye.x"));assertTrue(s.contains("marker.pose().point().y()-eye.y"));var observer=Files.readString(Path.of("src/main/java/dev/starfold/NativeSpaceClient.java"));assertTrue(observer.contains("mc.player.getEyePosition"));}
    @Test void scopeQuaternionCarriesFacingAndUpForAllDirections(){for(var d:Direction.values()){var forward=new org.joml.Vector3f(d.getStepX(),d.getStepY(),d.getStepZ());var up=d.getAxis()==Direction.Axis.Y?new org.joml.Vector3f(-1,0,0):new org.joml.Vector3f(0,1,0);var q=new org.joml.Quaternionf().lookAlong(forward,up).conjugate();assertTrue(new org.joml.Vector3f(0,0,-1).rotate(q).distance(forward)<1e-6);assertTrue(new org.joml.Vector3f(0,1,0).rotate(q).distance(up)<1e-6);}}
}
